custom_css:
/* 云间 · Cloud Correspondence 1.0.2 | SillyTavern 1.19.0
   原创软气泡与石墨深色。无外链图片 / 字体，--cc-* 支持工作台微调。 */
:root {
  --cc-theme: cloud-correspondence;
  --cc-base: #e3e9ef; /* 浅色底色 */
  --cc-accent: #6575b6; /* 浅色强调色 */
