  --cc-light: #ffffff; --cc-shade: #b7c3d3; --cc-edge: #f7faff;
  --cc-accent-ink: #4c5b9a; --cc-on-accent: #ffffff; --cc-user: #dbe2f1;
  --cc-depth: 1; /* 凹凸强度 */
  --cc-radius: 28px; /* 气泡圆角 */
  --cc-font-size: 17px; /* 正文字号 */
  --cc-line-height: 1.85; /* 正文行高 */
  --cc-gap: 28px; /* 消息间距 */
  --cc-avatar: 52px; /* 头像大小 */
  --cc-lift: calc(6px * var(--cc-depth)) calc(6px * var(--cc-depth)) calc(14px * var(--cc-depth)) var(--cc-shade), calc(-6px * var(--cc-depth)) calc(-6px * var(--cc-depth)) calc(14px * var(--cc-depth)) var(--cc-light);
  --cc-small: calc(3px * var(--cc-depth)) calc(3px * var(--cc-depth)) calc(7px * var(--cc-depth)) var(--cc-shade), calc(-3px * var(--cc-depth)) calc(-3px * var(--cc-depth)) calc(7px * var(--cc-depth)) var(--cc-light);
  --cc-inset: inset calc(3px * var(--cc-depth)) calc(3px * var(--cc-depth)) calc(7px * var(--cc-depth)) var(--cc-shade), inset calc(-3px * var(--cc-depth)) calc(-3px * var(--cc-depth)) calc(7px * var(--cc-depth)) var(--cc-light);
}
:root[data-cc-mode="dark"] {
  --cc-base: #292e32; --cc-accent: #dfa46b; --cc-ink: #e2e7e9; --cc-muted: #a2afb8;
  --cc-light: #394147; --cc-shade: #191d21; --cc-edge: #485159;
  --cc-accent-ink: #edb782; --cc-on-accent: #28241f; --cc-user: #30373e; color-scheme: dark;
}
:root:not([data-cc-mode="dark"]) { color-scheme: light; }
body {
  --SmartThemeBodyColor: var(--cc-ink); --SmartThemeEmColor: var(--cc-muted);
  --SmartThemeUnderlineColor: var(--cc-ink); --SmartThemeQuoteColor: var(--cc-accent-ink);
  --SmartThemeBlurTintColor: var(--cc-base); --SmartThemeChatTintColor: transparent;
  --SmartThemeUserMesBlurTintColor: var(--cc-user); --SmartThemeBotMesBlurTintColor: var(--cc-base);
  --SmartThemeBorderColor: color-mix(in srgb, var(--cc-ink) 15%, transparent);
  --SmartThemeShadowColor: transparent; --SmartThemeBlurStrength: 0px; --cc-reserved: 0px;
  --mainFontFamily: "Segoe UI", "Microsoft YaHei", "PingFang SC", system-ui, sans-serif;
  background: var(--cc-base); color: var(--cc-ink); text-shadow: none;
}
#bg1, #bg_custom { opacity: 0; pointer-events: none; }
#top-bar { background: transparent; box-shadow: none; border: 0; backdrop-filter: none; }
* { scrollbar-color: var(--cc-shade) transparent; scrollbar-width: thin; }
::selection { background: color-mix(in srgb, var(--cc-accent) 28%, var(--cc-base)); }
:where(button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 2px solid var(--cc-accent-ink); outline-offset: 3px; }
#sheld {
  inset: 22px calc(24px + var(--cc-reserved)) 22px 108px;
  width: min(var(--sheldWidth), calc(100% - 132px - var(--cc-reserved)));
  height: calc(100dvh - 44px); max-height: calc(100dvh - 44px);
  min-height: 0; margin: 0 auto; overflow: visible;
}
#chat {
  min-height: 0; max-height: none; flex: 1 1 0; background: transparent; border: 0; box-shadow: none;
  padding: 20px 28px 28px; gap: var(--cc-gap); overflow-x: hidden; overflow-y: auto;
  backdrop-filter: none; text-shadow: none; scroll-padding: 20px;
}
#chat .mes {
  --mes-right-spacing: 0px;
  display: grid; grid-template-columns: var(--cc-avatar) minmax(0, 1fr); column-gap: 14px; align-items: start;
